create or replace TABLE ART (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
	MWST_ID NUMBER(38,0) NOT NULL COMMENT 'Mehrwertsteuer - Kennzeichen.',
	LAND_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Herkunftsland.',
	REGION_ID NUMBER(38,0) NOT NULL COMMENT 'Region eines Landes, z.Bsp. Hessen, Kärnten. Wird im DWH als künstlicher Schlüssel über die SAP-Region gebildet.',
	KL_ART_ID NUMBER(38,0) NOT NULL COMMENT '7-stellige Artikelnummer bestehend aus 2 Stellen: Warengruppe 4 Stellen: Artikelnummer 1 Stelle: Prüfziffer.',
	DAT_VON DATE NOT NULL COMMENT 'Datum, ab welchem der Artikel im System angelegt wurde. Bei Artikeln älter als DWH: 1900-01-01.',
	DAT_BIS DATE NOT NULL COMMENT 'Reorganisations (Lösch)-Datum des Artikels in SAP. Bei nicht gelöschten Artikeln: ''9999-12-31''.',
	LOESCH_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Löschkennzeichen für logische Löschung, kann folgende Ausprägungen annehmen G: Gesperrt, R: Räumen, L: Gelöscht, blank: kein Löschkennzeichen.',
	BIO_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Biosiegel Flag EU, es gibt auch noch ein bio_fg_cz (Kürzel: BIO).',
	WG_ART_FG NUMBER(38,0) NOT NULL COMMENT 'Warengruppen-Artikel (wird auch als Sumpfartikel oder Warengruppen-Erfassungsartikel bezeichnet). Wird benutzt, wenn sich ein Artikel nicht eindeutig einer Artikelnummer zuordnen lässt. 0 = Nein; 1 = Ja.',
	POSTEN_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' DEFAULT '  ' COMMENT 'Postenkennzeichen. Für Artikel, die nicht ständig im Sortiment sind (für KMO ist es ein posten_fg, wenn das Posten-KZ in SAP wird eine 1 gesetzt).',
	LEAD_ID NUMBER(38,0) NOT NULL COMMENT 'Leaderkennzeichen.',
	LEIST_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Artikelkennzeichen Leistungsstark Food.',
	DISCOUNT_ID NUMBER(38,0) NOT NULL COMMENT 'Schlüssel des Discount Artikelkennzeichens - numerischer Wert (0 = kein Discountartikel, oder Kennzeichen zwischen 1 und 7).',
	VERPART_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'ID der Verpackungsart, z.Bsp DS.',
	ESB_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Kalkulationskennzeichen Nonfood. Inhalt = E für Einstiegspreislage, B für Blickpunktartikel. S = Strategieartikel. Wird nicht mehr benutzt.',
	ALDI_ID NUMBER(38,0) NOT NULL COMMENT 'Kennzeichnet, in welcher / welchen Vertriebsschiene(n) ein Artikel das Aldi Kennzeichen besitzt, kann sich auf eine oder mehrere Vertriebsschienen beziehen.',
	ZEK_ID VARCHAR(3) NOT NULL COMMENT 'Zentraleinkäufer-ID: Diese ID ist nicht mit der Mitarbeiter-ID identisch. So gesehen eine überflüssige ID.',
	GEWART_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Gewichtsartikel: ist bei Gewichtsartikeln = KG, bei Stückartikeln = ST.',
	EIGENMARKE_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Eigenmarken-Kennzeichen (z.Bsp. C für Kaufland Classik Artikel).',
	MUTTER_WB_ID NUMBER(38,0) COMMENT 'Bei einer Serie von Artikeln mit gleicher Werbung ist hier die Artikel_ID des führenden Artikels (auch: Mutterartikel) hinterlegt.',
	DISPLAY_ID NUMBER(38,0) COMMENT 'Schlüssel des Artikelkennzeichens Display (0 = kein Displayartikel).',
	BEST_MENGE_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Bestellmengeneinheit. Diese Mengeneinheit wird standardmäßig bei Bestellungen verwendet.',
	LOESCHVORM_FG NUMBER(38,0) DEFAULT -1 COMMENT 'Kennzeichen, dass Artikel zum Löschen vorgemerkt wird. 1 entspricht Ja.',
	MHD_ZEITRAUM NUMBER(38,0) COMMENT 'Dieses Feld gibt den standardmässigen Mindesthaltbarkeitszeitraum für diesen Artikel in Tagen an.',
	ARTIKELART_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Kategorisierung in Artikelarten (z. B. Batterien, Leergut, Sport-Schuhe). Referenz zu der Tabelle l_artikelart.',
	BASISMENGE_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Alternative Mengenheinheit für den Artikel in Basismenge. Referenz zu der Tabelle art_umrechnung_faktor_per.',
	FAKTOR_NETTOINHALT NUMBER(18,3) COMMENT 'Umrechnungsfaktor von Stück in Nettogewicht (wenn die Basismengeneinheit in Stück ausgewiesen ist). Aus SAP MARA.INHAL.',
	MUTTER_VK_ID NUMBER(38,0) COMMENT 'Bei einer Serie von Artikeln mit gleichen Verkaufspreisen ist hier die Artikel_ID des führenden Artikels (auch: Mutterartikel) hinterlegt.',
	LAGER_PROZENT NUMBER(38,0) NOT NULL DEFAULT 100 COMMENT 'Lagerprozentsatz. Gibt an, wieviel Prozent der Restlaufzeit noch nicht abgelaufen sein darf, wenn der Artikel vom Lager ausgeliefert wird.',
	TEMPERATUR_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Kennzeichen für den Temperaturbereich, z.Bsp. 3.',
	DUALES_SYSTEM_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Duales System-Gebühren (0 = nein, 1 = ja).',
	GRS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Gemeinsames Rücknahme System (für Batterien) -Gebühren (0=nein, 1 = ja).',
	EAR_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Elektro-Altgeräte-Register-Gebühren (0 = nein, 1 = ja).',
	GEMA_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für GEMA (Gesellschaft für musikalische Aufführungs- und mechanische Vervielfältigungsrechte) -relevante Artikel (0 = nein, 1 = ja).',
	LACTOSE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Lactosefreie Artikel.',
	GLUTEN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Gluten-freie Artikel.',
	DIAET_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag kennzeichnet Diät-Artikel.',
	ARTIKELTYP_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Klassifizierung des Artikels, z.Bsp. Displayartikel.',
	VERKAUF_SPERRE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kennzeichnet für den Verkkauf gesperrte Artikel. Nur in DE SAP vorhanden.',
	EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Maßeinheit aus mara.inhme. Referenz zur Tabelle l_einh (t006a).',
	PLATZ_RELEVANT_FG NUMBER(38,0) NOT NULL COMMENT 'Flag zur Kennzeichnung platzierungsrelevanter Artikel aus maw1.zzekplatz.',
	BITREX_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Bitrex Flag (Kürzel: BEX).',
	BLAUER_ENGEL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel Flag (Kürzel: BLA).',
	DACHLOGO_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Dachlogo Flag (Kürzel: DAC).',
	DOLPHIN_SAFE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Delfinsicherer Thunfischfang (Safe) Flag (Kürzel: DTU).',
	EURO_BLUME_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Europäisches Umweltzeichen Euro-Blume Flag (Kürzel: EBL).',
	ECOCERT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Ecocert Flag (Bio-Zertifizierung) Flag (Kürzel: ECO).',
	EIER_BH_FH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Eier aus Bodenhaltung / Freilandhaltung Flag (Kürzel: EIB).',
	FAIR_TRADE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Fair Trade Flag (Kürzel: FAT).',
	FOS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Friend of the sea -Logo Flag (Kürzel: FOS).',
	FSC_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Forest Stewardship Council -Logo Flag (Kürzel: FSC).',
	GAP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Gemeinsame Agrapolitik (GAP) Flag (Kürzel: GAP).',
	GOTS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: GOTS = Global Organic Textile Standard Flag (Kürzel: GOT).',
	HALAL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Halal Flag (Kürzel: HAL).',
	KANINCHEN_BH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Kaninchen aus Bodenhaltung Flag (Kürzel: KAB).',
	KEIMLING_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Keimling Flag (Kürzel: KEI).',
	KEIN_STOPF_RUPF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Keine Stopfmast / kein Lebendrupf Flag (Kürzel: KST).',
	MSC_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Marine Stewardship Council Flag (Kürzel: MSC).',
	KON_NAT_KOSMETIK_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Kontrollierte Naturkosmetik Flag (Kürzel: NAK).',
	NATRUE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: NaTrue Naturkosmetik-Siegel Flag (Kürzel: NAT).',
	NATURLAND_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Naturland Flag (Kürzel: NLA).',
	OHNE_GENTECHNIK_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: ohne Gentechnik Flag (Kürzel: OGE).',
	OEKO_TEX_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Textiles Vertrauen - Öko-Tex Standard 100 Flag (Kürzel: OTS).',
	PEFC_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: PEFC (= Programme for the Endorsement of Forest Certification Schemes) Nachhaltigkeit in der Waldwirtschaft Flag (Kürzel: PEF).',
	RAINFOREST_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Rainforest Alliance Flag (Kürzel: RAL).',
	SUSTAIN_CLEAN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: SCC = sustainable-cleaning-charter Logo für nachhaltiges Waschen und Reinigen Flag (Kürzel: SCC).',
	TIERSCHUTZ_GEPR_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Tierschutz geprüft Flag.',
	AQUAGAP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Aqua Gap Flag für nachhaltige Fischereiwirtschaft aus der Quelle zekstn (Kürzel: AQUAGAP).',
	SAISON_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'ID der Saison aus saiso, z.Bsp 9.',
	JUGENDSCHUTZ_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Jugendschutz Kennzeichen aus maw1.zzek_ekpom. Enthält eine Altersangabe (z.Bsp. 12,16,18).',
	FOLLOW_FISH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: FollowFish - Flag (Kürzel: FOLLOW_FISH).',
	GEPA_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: GEPA Fair Trade Flag (Kürzel: GEPA).',
	GREEN_BRANDS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Green Brands Flag.',
	NATURE_AND_RESPECT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Nature & Respect Flag für artgerechte Tierhaltung (Kürzel: NATURE_AND_RESPECT).',
	UTZ_CERTIFIED_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: UTZ Certified Flag für Kaffeeprodukte (Kürzel: UTZ_CERTIFIED).',
	OEKO_TEX_STD_100_PLUS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Ökotex Standard 100 Flag (Kürzel: OEKO_TEX_STD_100_PLUS).',
	VIER_PFOTEN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Vier Pfoten Flag (Kürzel: VIER_PFOTEN).',
	ASC_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: ASC Flag (Aquaculture Stewardship Council für nachhaltige Fischzucht aus Aquakultur) (Kürzel: ASC).',
	BAP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: BAP Flag (Best Aquaculture Practices) (Kürzel: BAP).',
	RSPO_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: RSPO Flag - Roundtable on Sustainable Palm Oil (Kürzel: RSPO).',
	KL_ART_ID_ALT NUMBER(38,0) COMMENT 'Vorgänger-Artikelnummer aus der Spalte bismt.',
	TAGESARTIKEL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Tagesartikel-Flag aus maw1.zzek_kztgar. Tagesartikel müssen innerhalb eines Tages verkauft werden.',
	KEIN_ABVERKAUF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kein-Abverkauf-Flag aus maw1.zzek_nsale. Wenn = 1, darf der Artikel nicht abverkauft werden.',
	DIV_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Diverse Logos Flag aus div (Kürzel: DIV).',
	FCP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: FT cocoa Flag aus fcp (Kürzel: FCP).',
	FW_SAISON_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID für das Fleischwerk-Artikel-Kennzeichen Saison aus dem Quellfeld zzfwarblock mit Referenz zu zfwprartik bzw.l_fw_saison.',
	FW_WK_SYSTEM_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID des Fleischwerk WK Artikelkennzeichens aus zzfwbeschaf, z.Bsp. Innereien.',
	FW_WK_DISCOUNT_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID für die Kennzeichnung fw_wk_discount aus dem Quellfeld zfwqualita.',
	FW_WK_NATIONAL_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID für die Kennzeichnung fw_wk_national aus dem Quellfeld zfwwarenar.',
	FW_WE_HAMMER_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID für die Kennzeichnung Fleischwerk WE-Hammer aus dem Quellfeld zfwveredel.',
	FW_WE_ARTIKEL_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID für die Kennzeichnung Fleischwerk WE-Artikel aus dem Quellfeld zfwprzuber.',
	FW_RESERVE_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'ID für die Kennzeichnung Artikel Fleischwerk Reserve aus dem Quellfeld zfwbestvor.',
	VEGAN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Vegan Flag aus vgn (Kürzel: VGN).',
	VEGETARISCH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Vegetarisch Flag aus vgt (Kürzel: VGT).',
	PSF_ID NUMBER(38,0) COMMENT 'ID des Produktschaufensters aus zzek_showcase, z.Bsp. 1.',
	MENGE_HAUS NUMBER(38,0) COMMENT 'Haushaltsübliche Menge aus zzek_hausmg.',
	SMGRP NUMBER(38,0) COMMENT 'Sortimentsmanagergruppe aus zzek_smgrp. Referenziert auf die Tabelle zek(t024).',
	TIERWOHL_KZ VARCHAR(2) COLLATE 'en-ci' COMMENT 'Kennzeichen Tierwohl, z.Bsp. sw für Schwein, aus dem Quellfeld zzek_tierwohl. Keine Lookup vorhanden.',
	GTIN_ID NUMBER(26,0) NOT NULL COMMENT 'Pro Artikel ist eine Haupt-GTIN vorhanden. Diese wird für KMO hier abgelegt. Für DE wird -1 eingetragen.',
	BIO_FG_CZ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Bio Flag CZ. Aus der Quelle SAP zek_sustain_set.pez.',
	VERHANDLER_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' DEFAULT '  ' COMMENT 'MAW1.ZZEK_ZEKKLMAVERH - Verhandler KL-Marke.',
	ZEK_VAT_ID VARCHAR(3) NOT NULL COMMENT 'Zentraleinkäufer-ID: Diese ID ist nicht mit der Mitarbeiter-ID identisch.',
	INHALT_MENGE_EINH_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Maßeinheit für das Feld Inhalt_Menge.',
	INHALT_MENGE NUMBER(18,3) COMMENT 'Inhaltsmenge (abhängig von der Maßeinheit (inhalt_menge_einh_id).',
	KEIN_VK_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag kein Verkaufsartikel (1 = kein Verkaufsartikel).',
	GOTS_ORGAN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Global Organic Textile Standard (Kürzel: GOO).',
	GOTS_PROZ_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Global Organic Textile Standard - made with x% organic materials (Kürzel: GOP).',
	GU_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Geschützte Ursprungsbezeichnung (Kürzel: PDO).',
	GGA_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Geschützte Geografische Angabe (Kürzel: PGI).',
	FSC_VERPACKUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: FSC Verpackung (Kürzel: PVP).',
	RAINF_KAKAO_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Rainf_Kakao (Kürzel: RKA).',
	RAINF_KAFFEE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Rainf_Kaffee (Kürzel: RKF).',
	GTS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Garantiert traditionelle Spezialität (Kürzel: TSG).',
	BLAUER_ENGEL_ABBAUBAR_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_abbaubar (Kürzel: BAB).',
	BLAUER_ENGEL_ALTPAPIER_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Altpapier (Kürzel: BAL).',
	BIO_BW_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Bio BW (Kürzel: BBW).',
	BIOLAND_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Bioland (Kürzel: BIL).',
	BLAUER_ENGEL_KUNSTSTOFF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Kunststoff (Kürzel: BKU).',
	BLAUER_ENGEL_MEHRWEG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Mehrweg (Kürzel: BME).',
	BLAUER_ENGEL_WIRKSTOFF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Wirkstoff (Kürzel: BOW).',
	BLAUER_ENGEL_WASSER2_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Wasser_2 (Kürzel: BSA).',
	BLAUER_ENGEL_SOLARBETRIEB_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Solarbetrieb (Kürzel: BSO).',
	BLAUER_ENGEL_UNGEBLEICHT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Blauer Engel_Ungebleicht (Kürzel: BUG).',
	DTB_EINSTIEG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Deutscher Tierschutzbund Einstiegsstufe (Kürzel: DTE).',
	DTB_PREMIUM_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Deutscher Tierschutzbund Premiumstufe (Kürzel: DTE).',
	FREILANDHALTUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Freilandhaltung (Kürzel: FDH).',
	NEULAND_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Neuland (Kürzel: NEL).',
	QS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: QS-Prüfzeichen für Lebensmittel (Kürzel: QSP).',
	WEIDEHALTUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Weidehaltung (Kürzel: WDH).',
	TIERWOHL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Initiative Tierwohl (Kürzel: ITW).',
	MARKTFRISCH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: Marktfrisch (Kürzel: MAF).',
	YELLOWPRINT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Gelbes Regaletikett.',
	IPN_ID NUMBER(18,0) COMMENT 'Internationale Produktnummer zum Artikel (MAW1.ZZEK_IPN).',
	POSTEN_KZ_SAP VARCHAR(2) NOT NULL COLLATE 'en-ci' DEFAULT '  ' COMMENT 'Postenkennzeichen. Für Artikel, die nicht ständig im Sortiment sind (Unterschied zur posten_id: für KMO werden die tatsächlichen Werte aus SAP gespeichert) (z.B PN = Posten, SP = sortimentsnahe Posten, etc.).',
	DEMETER_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag für Demeter-Artikel.',
	KAUFEMPFEHLUNG_FG NUMBER(38,0) COMMENT 'Flag Kaufempfehlung (0 = nein, 1 = ja).',
