	DISCOUNTART_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'ID Discountart.',
	POSITIONSTYP_GRP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' DEFAULT '    ' COMMENT 'ID allgemeine Positionstypengruppe.',
	ARTIKELROLLE_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Artikelrolle international ID.',
	UNSERE_REGION_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Artikel ist aus der Region (BG).',
	LETS_BBQ_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Artikel hat das Saisonkennzeichen ''Let''s Barbeque''.',
	VERPACKUNGSEINSPARUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Verpackungsmaterial wurde beim Artikel gespart.',
