	ZUM_FASTEN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Artikel zum Fasten geeignet.',
	KL_BESONDERES_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Besonderes bei Kaufland.',
	STAHLHALTUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Haltungsform 1_Stallhaltung.',
	STAHLHALTUNG_PLUS_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Haltungsform 2_Stallhaltung Plus.',
	AUSSENKLIMA_HALTUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Haltungsform 3_Außenklima.',
	PREMIUM_HALTUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Haltungsform 4_Premium.',
	MACHEN_MACHT_UNTERSCHIED_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Artikelslogan: K-CSR_Machen macht den Untersch.',
	PREMIUM_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Saison Kennzeichen: Premium.',
	QAFP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'QAFP - quality control sign.',
	QUDAL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'QUDAL - Top quality medal.',
	REGIONALE_LEBENSMITTEL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: SAP Icon ''RPO''. Regional food (CZ).',
	STARTUP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Startup Artikel - startup by Kaufland.',
	TOGO_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Saisonkennzeichen: ToGo.',
	OHNE_MICROPLASTIK_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Rezeptur ohne Mikroplastik.',
	GRK_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Grüner Knopf.',
	PPL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Produkt Polski.',
	BEV_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'BV Verpackungsmaterialeinsparung.',
	RPP_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Online Click & Collect.',
	RSC_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Online Supermercato.',
