	NAT_BIO_SIEGEL_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: SAP Icon ''NBS''. Ein Bio-Siegel ist ein Güte- und Prüfsiegel, mit welchem Erzeugnisse aus ökologischem Landbau gekennzeichnet werden.',
	FAIR_SUGAR_PROG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachhaltigkeitslogo: SAP Icon ''FSP''. Fairtrade Sugar Program (FSI).',
